// --- CONFIGURAÇÃO MESTRE: BAZACAS ODONTO (Multi-Unidade) ---
const body = $input.item.json.body || $input.item.json;

const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || '';

const telefoneRaw   = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente  = body.nome_cliente || body.nome_contato || 'Paciente';
const insistiu      = body.insistiu === true || body.insistiu === 'true';

const unidadeRaw = (
  body.unidade      ||
  body.clinica      ||
  body.local        ||
  body.unit         ||
  body.nome_unidade ||
  ''
).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const TIMEZONE = 'America/Sao_Paulo';

// ── Parse de datas ────────────────────────────────────────────
const hoje       = DateTime.now().setZone(TIMEZONE);
const dataInicio = hoje.toFormat('yyyy-MM-dd');

const dataRaw = body.data_iso || body.data_inicio || body.data_agendada || '';
let dtP = null;
if (dataRaw) {
  dtP = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
}

const horaDoISO = (dtP && dtP.isValid && (dtP.hour > 0 || dtP.minute > 0))
  ? dtP.toFormat('HH:mm') : '';

const horaFinal = (body.horario_agendado && body.horario_agendado.length >= 4)
  ? body.horario_agendado
  : (body.horario && body.horario.length >= 4)
  ? body.horario
  : horaDoISO;

const dataFinal = (dtP && dtP.isValid) ? dtP.toFormat('yyyy-MM-dd') : '';
const dataFim   = (dtP && dtP.isValid)
  ? dtP.plus({ days: 7 }).toFormat('yyyy-MM-dd')
  : hoje.plus({ days: 7 }).toFormat('yyyy-MM-dd');

// ── Mapa de unidades ──────────────────────────────────────────
const CONFIGS = {
  saojeronimo: {
    subscriber_id:         '16799539000354',
    business_id:           '6617823469240320',
    nome_unidade:          'Bazacas São Jerônimo',
    nome_empresa:          'Bazacas Odonto',
    link_agenda:           '761819',
    duracao_servico:       30,
    capacidade_simultanea: 2,
    profissionais: {
      '6586006258647040': 'Dra. Luisa Johnson Reck',
      '6012144584884224': 'Dra. Marina Athanazio Mocelin'
    },
    authorization: 'Basic ' + Buffer.from('saojeronimo:9a2e56ce-a361-4df8-9a64-1f63a947f65c').toString('base64')
  },
  butia: {
    subscriber_id:         '16799539000273',
    business_id:           '5020229785747456',
    nome_unidade:          'Bazacas Butiá',
    nome_empresa:          'Bazacas Odonto',
    link_agenda:           '80721',
    duracao_servico:       30,
    capacidade_simultanea: 2,
    profissionais: {
      '5329347864035328': 'Dra. Marina Athanazio Mocelin',
      '5979415075422208': 'Dra. Luisa Johnson Reck',
    },
    authorization: 'Basic ' + Buffer.from('butia:8a2c85fa-fa54-4ff9-a5e0-6759ca831a5c').toString('base64')
  },
  arroiodosratos: {
    subscriber_id:         '16799539000192',
    business_id:           '6492004684005376',
    nome_unidade:          'Bazacas Arroio dos Ratos',
    nome_empresa:          'Bazacas Odonto',
    link_agenda:           '900710',
    duracao_servico:       30,
    capacidade_simultanea: 2,
    profissionais: {
      '5300487381909504': 'Dra. Luisa Johnson Reck',
      '4778713695780864': 'Dra. Marina Athanazio Mocelin',
    },
    authorization: 'Basic ' + Buffer.from('arroiodosratos:106940db-7f20-4aff-a567-1c54580597dc').toString('base64')
  }
