// ── Roteamento por unidade ────────────────────────────────────
let chave = null;

if (
  unidadeRaw.includes('jeronimo') ||
  unidadeRaw.includes('sao jer')  ||
  unidadeRaw.includes('s. jer')   ||
  unidadeRaw.includes('sjeronimo')
) {
  chave = 'saojeronimo';
} else if (
  unidadeRaw.includes('butia') ||
  unidadeRaw.includes('buti')
