    nome_paciente:       nomePaciente,
    telefone_limpo:      telefoneLimpo,
    insistiu:            insistiu,
    data_nascimento:     body.data_nascimento || '',
    data_inicio:         dataInicio,
    data_agendada:       dataFinal,
    data_antiga:         body.data_antiga || body['data-antiga'] || '',
    data_fim:            dataFim,
    horario_agendado:    horaFinal,
    horario_preferido:   body.horario_preferido || null,
    spin:                body.SPIN || body.spin || null,
    unidade_selecionada: chave,
    config_agenda: {
      subscriber_id:            CONFIG.subscriber_id,
      business_id:              CONFIG.business_id,
      nome_unidade:             CONFIG.nome_unidade,
      nome_empresa:             CONFIG.nome_empresa,
      link_agenda:              CONFIG.link_agenda,
      duracao_servico:          CONFIG.duracao_servico,
      capacidade_simultanea:    CONFIG.capacidade_simultanea,
      timezone:                 CONFIG.timezone,
      limite_dias_busca_normal: CONFIG.limite_dias_busca_normal,
      profissionais:            CONFIG.profissionais,
      authorization:            CONFIG.authorization
    }
  }
};

// =============================================================
// LÓGICA BAZACAS DISPARO v1.0
// Retorna apenas horários disponíveis na data fixa do evento
// Sem redirecionamento para outras datas — o agente controla o fluxo
// =============================================================

const cfgNode = $('Configuracao Unidades').first().json;
const ca = cfgNode.config_agenda || {};

const TIMEZONE = ca.timezone || 'America/Sao_Paulo';
const PROF_MAP  = ca.profissionais || {};

const diasAPI       = $input.all().map(i => i.json);
const hPreferido    = cfgNode.horario_preferido || null;
const dRaw          = cfgNode.data_agendada || '';
const hRaw          = cfgNode.horario_agendado || '';

// ── Helpers ──────────────────────────────────────────────────

function horaParaMin(str) {
  if (!str) return -1;
  const p = str.split(':');
  return parseInt(p[0]) * 60 + parseInt(p[1] || '0');
}

function processarDia(dia) {
  const slots = (dia.AvaliableTimes || []).filter(s => {
    if (s.isSelectable !== true) return false;
    const profId = String(s.professionalId || '');
    return !!PROF_MAP[profId];
  });

  return slots.map(slot => {
    const profId   = String(slot.professionalId || '');
    const profNome = PROF_MAP[profId];
    return {
      data:        dia.jsonDate,
      semana:      dia.Week,
      minutos:     horaParaMin(slot.from),
      horario:     slot.from,
      horario_fim: slot.to,
      profId,
      profNome
    };
  }).sort((a, b) => a.minutos - b.minutos);
}

function fmtBloco(b) {
  const [yyyy, mm, dd] = b.data.split('-');
  return `🗓️ *${dd}/${mm} (${b.semana})* às *${b.horario}* – *${b.horario_fim}* com ${b.profNome}`;
}

function sugerirPorPreferido(blocos, hPref, n = 2) {
  const minPref = horaParaMin(hPref);
  return [...blocos]
    .sort((a, b) => Math.abs(a.minutos - minPref) - Math.abs(b.minutos - minPref))
    .slice(0, n);
}

// ── Processamento ────────────────────────────────────────────

let todosBlocos = [];
for (const dia of diasAPI) todosBlocos = todosBlocos.concat(processarDia(dia));

// Filtrar apenas a data fixa do evento solicitada
const blocosDoDia = dRaw
  ? todosBlocos.filter(b => b.data === dRaw)
  : todosBlocos;

const sugestoesHorarios = [];
let resultado;

if (blocosDoDia.length === 0) {
  // Sem horários na data — agente cuida do contorno (2ª data ou unidade alternativa)
  resultado = `😕 Não há horários disponíveis para esta data.`;

} else {
  // Selecionar até 2 opções — priorizando preferência de horário se informada
  const opcoes = hPreferido
    ? sugerirPorPreferido(blocosDoDia, hPreferido, 2)
    : blocosDoDia.slice(0, 2);

  opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));

  const [yyyy, mm, dd] = dRaw.split('-');
  const dtLabel = dRaw ? `${dd}/${mm}` : 'data solicitada';

  const prefLabel = hPreferido
    ? `\n\n💡 _Priorizei horários próximos à sua preferência: *${hPreferido}*_`
    : '';

  resultado =
    `📅 Encontrei os seguintes horários disponíveis para *${dtLabel}*:${prefLabel}\n\n` +
    opcoes.map(fmtBloco).join('\n') +
    `\n\nNesses horários, qual fica melhor pra você?`;
}

return {
  json: {
    resultado,
    sugestoes_horarios:   sugestoesHorarios,
    total_blocos_validos: blocosDoDia.length
  }
};

// ── Validar Slot Agendar — Bazacas (prioriza profissional conhecido) ──
let d = {};
try { d = $('Configuracao Unidades').first().json; } catch(e) { d = $input.item.json; }

const PROF_MAP = d.config_agenda?.profissionais || {};

const inputItems    = $input.all().map(i => i.json);
const isNovoFormato = inputItems.length > 0 && Array.isArray(inputItems[0].AvaliableTimes);

let slots = [];
if (isNovoFormato) {
  slots = (inputItems[0].AvaliableTimes || []).filter(s => s.isSelectable === true);
} else {
  slots = inputItems;
}

const norm = h => {
  if (!h) return '';
  const p = h.toString().split(':');
  return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'00');
};

const hAlvo = norm(d.horario_agendado || '');

let v = { aprovado: false, motivo: 'Horário indisponível.' };
let idF = null, nomeF = '';

if (!slots.length) {
  v.motivo = 'Não há agenda aberta ou horários disponíveis neste dia.';
} else if (!hAlvo) {
  v.motivo = 'Horário solicitado não informado.';
} else {
  const slotsDoHorario = slots.filter(s => {
    const from   = norm(isNovoFormato ? s.from : s.From);
    const profId = isNovoFormato ? s.professionalId : s.ProfessionalId;
    return from === hAlvo && !!profId;
  });

  const slotConhecido = slotsDoHorario.find(s => {
    const profId = String(isNovoFormato ? s.professionalId : s.ProfessionalId);
    return !!PROF_MAP[profId];
  });

  const slotEncontrado = slotConhecido || null;

  if (slotEncontrado) {
    idF   = String(isNovoFormato ? slotEncontrado.professionalId : slotEncontrado.ProfessionalId);
    nomeF = PROF_MAP[idF] || null;
    v     = { aprovado: true, motivo: 'Horário disponível.' };
  } else {
    v.motivo = `O horário ${d.horario_agendado} não está disponível.`;
  }
}

return {
  json: {
    ...d,
    validacao:               v,
    id_profissional_final:   idF,
    nome_profissional_final: nomeF,
    hora_buscada:            hAlvo,
    slots_encontrados_total: slots.length,
  }
};

